-- ========================================================================
-- MIGRACIÓN DE BANCO DE PREGUNTAS COMPLETO (1.506 PREGUNTAS)
-- ========================================================================


CREATE TABLE IF NOT EXISTS public.db_trivia_questions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  id_categoria TEXT NOT NULL,
  categoria_nombre TEXT NOT NULL,
  dificultad TEXT DEFAULT 'media',
  pregunta TEXT NOT NULL,
  opciones JSONB NOT NULL,
  respuesta_correcta_index INTEGER NOT NULL,
  fundamento_juridico TEXT,
  puntos_base INTEGER DEFAULT 100,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE public.db_trivia_questions ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Lectura pública de preguntas" 
  ON public.db_trivia_questions FOR SELECT 
  USING (true);

